"""Weekly timesheet rows built from a list of shifts."""

from typing import Iterable, List, Tuple

from hourglass.errors import ProjectError
from hourglass.models import Shift

def _check(shift: Shift) -> Shift:
    if not shift.worker.strip():
        raise ProjectError("blank worker name on a shift")
    return shift

def _tally(shifts: List[Shift]) -> dict:
    tally = {}
    for shift in map(_check, shifts):
        count, mins = tally.get(shift.worker, (0, 0))
        mins += shift.span.minutes
        tally[shift.worker] = (count + 1, mins)
    return tally

def _busiest(item: Tuple[str, Tuple[int, int]]) -> tuple:
    name, (count, minutes) = item
    return (-minutes, -count, name)

def _format_row(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

# ---
def format_timesheet(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    shifts = list(shifts)
    if not shifts:
        raise ProjectError("no shifts given")
    rows = sorted(_tally(shifts).items(), key=_busiest)
    return [_format_row(n, *v) for n, v in rows]

