# owner: platform
import unittest

from hourglass.timesheet import format_timesheet
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start, end))

class TimesheetTests(unittest.TestCase):
    def test_empty_raises(self):
        with self.assertRaises(ProjectError):
            format_timesheet([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ProjectError):
            format_timesheet([shift("  ", 60, 120)])

    def test_one_line_per_worker(self):
        lines = format_timesheet([
            shift("Ana", 480, 750),
            shift("Ana", 480, 600, "tue")
        ])
        self.assertEqual(
            lines, ["Ana: 2 shifts, 6.5 hours"]
        )

    def test_busiest_first(self):
        lines = format_timesheet([
            shift("Bo", 480, 540),
            shift("Cy", 480, 720),
            shift("Al", 480, 540)
        ])
        names = [line.split(":")[0] for line in lines]
        self.assertEqual(names, ["Cy", "Al", "Bo"])

    def test_accepts_iterator(self):
        lines = format_timesheet(iter([shift("Di", 0, 90)]))
        self.assertEqual(lines, ["Di: 1 shifts, 1.5 hours"])
